    'methodology.title': 'How We Calculate Safety Scores',
    'methodology.description': 'Our scoring methodology, data sources, and the rationale behind our safety ratings.',
    'methodology.overview_title': 'Overview',
    'methodology.overview_text': 'We aggregate data from 40+ trusted public sources to compute a composite safety score (1-10) for every country. Higher scores indicate safer destinations. Our hybrid scoring engine uses a weighted geometric mean across five categories — Conflict (30%), Crime (25%), Health (20%), Governance (15%), and Environment (10%) — so that a single critical weakness (e.g. active war) cannot be masked by strong scores elsewhere. Additional safety nets include a hard cap when a majority of government advisories issue "Do Not Travel" warnings, a critical floor when any category falls below a danger threshold, and advisory-based blending for countries with limited data coverage.',
    'methodology.sources_title': 'Data Sources',
    'methodology.formula_title': 'Scoring Formula',
    'methodology.formula_text': 'Raw indicator values are normalized to a 0-1 scale (higher = safer). Within each pillar, indicators have explicit sub-weights and are blended via baseline (~70%) and signal (~30%) tiers with exponential freshness decay. The composite score uses a weighted geometric mean of the five pillar scores — unlike an arithmetic mean, a geometric mean ensures that a single dangerously low pillar drags the overall score down significantly. Three additional safety mechanisms apply: (1) if a majority of government advisories reach Level 4 "Do Not Travel", the score is capped proportionally to the worst pillar; (2) if any pillar with data falls below a critical threshold, the score is capped to the weakest pillar; (3) for countries with limited data coverage, the score blends toward an advisory-derived estimate.',
    'methodology.tiered_title': 'Baseline + Signal Architecture',
    'methodology.tiered_text': 'Baseline sources (World Bank, V-Dem, INFORM, GPI) are updated annually and provide a stable foundation for scoring. Signal sources (ReliefWeb, GDACS, and 37 government travel advisories from countries spanning all continents) update daily or weekly and capture emerging crises such as armed conflicts, natural disasters, and disease outbreaks. Signal source influence is capped at 30% within each pillar, ensuring that volatile short-term data cannot dominate long-term structural indicators.',
    'methodology.decay_title': 'Data Freshness Decay',
    'methodology.decay_text': 'Each data source has a configured half-life for freshness decay. If a source\'s data is one half-life old, it contributes 50% of its full weight; at two half-lives, 25%; and so on. Beyond the configured maximum age, stale data is dropped entirely. This ensures scores always reflect the most current available information while gracefully degrading when sources are temporarily unavailable.',
    'methodology.weights_title': 'Category Weights',
    'methodology.weights_text': 'Categories are weighted to reflect their relative importance to traveler safety. Conflict carries the highest weight (30%) because active conflicts pose the most immediate and severe risk. Crime contributes 25%, as it directly affects personal safety day-to-day. Health (20%) remains important but is often manageable with precautions. Governance (15%) captures institutional stability as an indirect factor. Environment (10%) reflects natural and climate hazards that, while relevant, tend to be more localized or seasonal.',
    'methodology.sentiment_title': 'Community Sentiment',
    'methodology.sentiment_text': 'Below each country\'s five data-driven pillars, visitors can calibrate the overall safety score with a simple 5-level vote: way too high, too high, about right, too low, or way too low. We aggregate these votes into a community correction, capped at ±1.0 point so it can only nudge the algorithmic score, never override it. In this first phase, Community Sentiment is display-only — it does not affect the total safety score. We may weight it into the score in a future phase.',
    'methodology.limitations_title': 'Limitations and Caveats',
    'methodology.limitations_text': 'Our scores are based on publicly available data that may be delayed, incomplete, or not granular enough to capture regional differences within a country. Scores should be used as a general guide, not as definitive safety assessments. Always consult your government\'s official travel advisories before making travel decisions.',
    'methodology.indicator.gpi_overall': 'Global Peace Index - Overall Score',

