    'about.heading': 'About IsItSafeToTravel',
    'about.project_title': 'About the Project',
    'about.project_text': 'IsItSafeToTravel is a free, open-source travel safety platform that provides composite safety scores for 248 countries worldwide. Scores are computed daily from 7 trusted public sources: World Bank, V-Dem Institute (v16), INFORM Risk Index, Global Peace Index, ReliefWeb, GDACS, and government travel advisories from the US, UK, Canada, and Australia.',
    'about.mission_title': 'Mission',
    'about.mission_text': 'Our mission is to make travel safety information transparent, accessible, and data-driven. Every score is backed by publicly verifiable sources, and our methodology is fully documented.',
    'about.author_title': 'Author',
    'about.author_text': 'IsItSafeToTravel is created and maintained by Riccardo Dominici, an independent developer and data analyst. The project is built with a focus on data transparency, automated pipelines, and open-source principles.',
