    'methodology.description': 'La nostra metodologia di punteggio, le fonti dei dati e le motivazioni dietro le nostre valutazioni di sicurezza.',
    'methodology.overview_title': 'Panoramica',
    'methodology.overview_text': 'Aggreghiamo dati da oltre 40 fonti pubbliche affidabili per calcolare un punteggio composito di sicurezza (1-10) per ogni paese. Punteggi piu alti indicano destinazioni piu sicure. Il nostro motore di scoring ibrido utilizza una media geometrica ponderata su cinque categorie — Conflitto (30%), Criminalita (25%), Salute (20%), Governance (15%) e Ambiente (10%) — cosi che una singola debolezza critica (es. guerra attiva) non possa essere mascherata da punteggi alti altrove. Ulteriori meccanismi di sicurezza includono un tetto massimo quando la maggioranza dei governi emette avvisi "Non viaggiare", una soglia critica che limita il punteggio quando una categoria scende sotto un livello di pericolo, e un bilanciamento basato sugli advisory per i paesi con copertura dati limitata.',
    'methodology.sources_title': 'Fonti dei Dati',
    'methodology.formula_title': 'Formula di Calcolo',
    'methodology.formula_text': 'I valori grezzi degli indicatori vengono normalizzati su una scala 0-1 (piu alto = piu sicuro). All\'interno di ogni pilastro, gli indicatori hanno sotto-pesi espliciti e vengono combinati tramite livelli base (~70%) e segnale (~30%) con decadimento esponenziale della freschezza. Il punteggio composito utilizza una media geometrica ponderata dei cinque pilastri — a differenza della media aritmetica, la media geometrica garantisce che un singolo pilastro pericolosamente basso trascini significativamente il punteggio complessivo. Tre meccanismi di sicurezza aggiuntivi: (1) se la maggioranza degli avvisi governativi raggiunge il Livello 4 "Non viaggiare", il punteggio viene limitato proporzionalmente al pilastro peggiore; (2) se un pilastro con dati scende sotto una soglia critica, il punteggio e limitato al pilastro piu debole; (3) per i paesi con copertura dati limitata, il punteggio viene bilanciato verso una stima derivata dagli advisory.',
    'methodology.tiered_title': 'Architettura Base + Segnale',
    'methodology.tiered_text': 'Le fonti di base (Banca Mondiale, V-Dem, INFORM, GPI) vengono aggiornate annualmente e forniscono una base stabile per il punteggio. Le fonti di segnale (ReliefWeb, GDACS e 37 avvisi di viaggio governativi da paesi di tutti i continenti) si aggiornano quotidianamente o settimanalmente e catturano crisi emergenti come conflitti armati, disastri naturali e epidemie. L\'influenza delle fonti di segnale e limitata al 30% all\'interno di ogni pilastro, garantendo che i dati volatili a breve termine non possano dominare gli indicatori strutturali a lungo termine.',
    'methodology.decay_title': 'Decadimento della Freschezza dei Dati',
    'methodology.decay_text': 'Ogni fonte dati ha un\'emivita configurata per il decadimento della freschezza. Se i dati di una fonte hanno un\'emivita, contribuiscono al 50% del loro peso pieno; a due emivite, al 25%; e cosi via. Oltre l\'eta massima configurata, i dati obsoleti vengono eliminati completamente. Questo garantisce che i punteggi riflettano sempre le informazioni piu attuali disponibili, degradando gradualmente quando le fonti sono temporaneamente non disponibili.',
    'methodology.weights_title': 'Pesi delle Categorie',
    'methodology.weights_text': 'Le categorie sono ponderate per riflettere la loro importanza relativa per la sicurezza dei viaggiatori. Il Conflitto ha il peso maggiore (30%) perche i conflitti attivi rappresentano il rischio piu immediato e grave. La Criminalita contribuisce al 25%, in quanto influenza direttamente la sicurezza personale quotidiana. La Salute (20%) resta importante ma e spesso gestibile con precauzioni. La Governance (15%) cattura la stabilita istituzionale come fattore indiretto. L\'Ambiente (10%) riflette i rischi naturali e climatici che, pur essendo rilevanti, tendono ad essere piu localizzati o stagionali.',
    'methodology.sentiment_title': 'Sentiment della Community',
    'methodology.sentiment_text': 'Sotto i cinque pilastri basati sui dati di ogni paese, i visitatori possono calibrare il punteggio di sicurezza complessivo con un semplice voto a 5 livelli: molto alto, alto, giusto, basso o molto basso. Aggreghiamo questi voti in una correzione della community, limitata a ±1,0 punti in modo che possa solo influenzare leggermente il punteggio algoritmico, mai sostituirlo. In questa prima fase, il Sentiment della Community e solo visualizzato — non influisce sul punteggio di sicurezza totale. Potremmo integrarlo nel punteggio in una fase futura.',
    'methodology.limitations_title': 'Limitazioni e Avvertenze',
    'methodology.limitations_text': 'I nostri punteggi si basano su dati pubblicamente disponibili che possono essere ritardati, incompleti o non sufficientemente granulari per catturare le differenze regionali all\'interno di un paese. I punteggi devono essere utilizzati come guida generale, non come valutazioni definitive della sicurezza. Consulta sempre gli avvisi di viaggio ufficiali del tuo governo prima di prendere decisioni di viaggio.',
    'methodology.indicator.gpi_overall': 'Indice Globale della Pace - Punteggio Complessivo',

