    'donate.thanks': 'Dal profondo del cuore, grazie! Ogni contributo, anche il piu piccolo, fa una vera differenza e ci aiuta a mantenere questo progetto vivo per i viaggiatori di tutto il mondo. Siete fantastici!',
    'nav.donate': 'Sostienici',
    'about.title': 'Chi Siamo - IsItSafeToTravel',
    'about.description': 'Scopri il team, la missione e la metodologia dietro i punteggi di sicurezza di IsItSafeToTravel.',
    'footer.about': 'Chi Siamo',
    'about.heading': 'Chi Siamo',
    'about.project_title': 'Il Progetto',
    'about.project_text': 'IsItSafeToTravel e una piattaforma gratuita e open-source per la sicurezza dei viaggi che fornisce punteggi di sicurezza compositi per 248 paesi nel mondo. I punteggi vengono calcolati quotidianamente da 7 fonti pubbliche affidabili: Banca Mondiale, V-Dem Institute (v16), INFORM, Global Peace Index, ReliefWeb, GDACS e gli avvisi di viaggio governativi di USA, UK, Canada e Australia.',
    'about.mission_title': 'Missione',
    'about.mission_text': 'La nostra missione e rendere le informazioni sulla sicurezza dei viaggi trasparenti, accessibili e basate sui dati. Ogni punteggio e supportato da fonti pubblicamente verificabili e la nostra metodologia e completamente documentata.',
    'about.author_title': 'Autore',
    'about.author_text': 'IsItSafeToTravel e creato e mantenuto da Riccardo Dominici, sviluppatore indipendente e analista di dati. Il progetto e costruito con un focus sulla trasparenza dei dati, pipeline automatizzate e principi open-source.',
    'about.sources_title': 'Fonti dei Dati',
    'about.sources_text': 'Aggreghiamo dati da 7 fonti pubbliche aggiornate quotidianamente. Consulta la nostra {methodology_link} per tutti i dettagli su come vengono calcolati i punteggi.',
