    'methodology.title': 'Como Calculamos las Puntuaciones de Seguridad',
    'methodology.description': 'Nuestra metodologia de puntuacion, fuentes de datos y la logica detras de nuestras calificaciones de seguridad.',
    'methodology.overview_title': 'Vision General',
    'methodology.overview_text': 'Agregamos datos de mas de 40 fuentes publicas confiables para calcular una puntuacion compuesta de seguridad (1-10) para cada pais. Las puntuaciones mas altas indican destinos mas seguros. Nuestro motor de puntuacion hibrido utiliza una media geometrica ponderada de cinco categorias — Conflicto (30%), Criminalidad (25%), Salud (20%), Gobernanza (15%) y Medio Ambiente (10%) — para que una sola debilidad critica (ej. guerra activa) no pueda ser enmascarada por puntuaciones altas en otros aspectos. Mecanismos de seguridad adicionales incluyen un tope maximo cuando la mayoria de los gobiernos emiten avisos de "No viajar", un piso critico que limita la puntuacion cuando cualquier categoria cae por debajo de un umbral de peligro, y un balance basado en avisos para paises con cobertura de datos limitada.',
    'methodology.sources_title': 'Fuentes de Datos',
    'methodology.formula_title': 'Formula de Calculo',
    'methodology.formula_text': 'Los valores brutos de los indicadores se normalizan en una escala de 0-1 (mayor = mas seguro). Dentro de cada pilar, los indicadores tienen sub-pesos explicitos y se combinan mediante niveles de base (~70%) y senal (~30%) con decaimiento exponencial de frescura. La puntuacion compuesta utiliza una media geometrica ponderada de los cinco pilares — a diferencia de la media aritmetica, la media geometrica asegura que un solo pilar peligrosamente bajo arrastre significativamente la puntuacion general. Tres mecanismos de seguridad adicionales: (1) si la mayoria de los avisos gubernamentales alcanzan el Nivel 4 "No viajar", la puntuacion se limita proporcionalmente al pilar mas debil; (2) si algun pilar con datos cae por debajo de un umbral critico, la puntuacion se limita al pilar mas debil; (3) para paises con cobertura de datos limitada, la puntuacion se balancea hacia una estimacion derivada de los avisos.',
    'methodology.tiered_title': 'Arquitectura Base + Senal',
    'methodology.tiered_text': 'Las fuentes de base (Banco Mundial, V-Dem, INFORM, GPI) se actualizan anualmente y proporcionan una base estable para la puntuacion. Las fuentes de senal (ReliefWeb, GDACS y 37 avisos de viaje gubernamentales de paises de todos los continentes) se actualizan diaria o semanalmente y capturan crisis emergentes como conflictos armados, desastres naturales y brotes de enfermedades. La influencia de las fuentes de senal esta limitada al 30% dentro de cada pilar, asegurando que los datos volatiles a corto plazo no dominen los indicadores estructurales a largo plazo.',
    'methodology.decay_title': 'Decaimiento de Frescura de Datos',
    'methodology.decay_text': 'Cada fuente de datos tiene una vida media configurada para el decaimiento de frescura. Si los datos de una fuente tienen una vida media de antiguedad, contribuyen con el 50% de su peso total; a dos vidas medias, el 25%; y asi sucesivamente. Mas alla de la edad maxima configurada, los datos obsoletos se eliminan por completo. Esto asegura que las puntuaciones siempre reflejen la informacion mas actual disponible, degradandose gradualmente cuando las fuentes no estan disponibles temporalmente.',
    'methodology.weights_title': 'Pesos de las Categorias',
    'methodology.weights_text': 'Las categorias se ponderan para reflejar su importancia relativa para la seguridad de los viajeros. El Conflicto tiene el mayor peso (30%) porque los conflictos activos representan el riesgo mas inmediato y grave. La Criminalidad contribuye al 25%, ya que afecta directamente la seguridad personal diaria. La Salud (20%) sigue siendo importante pero a menudo es manejable con precauciones. La Gobernanza (15%) captura la estabilidad institucional como factor indirecto. El Medio Ambiente (10%) refleja los riesgos naturales y climaticos que, aunque relevantes, tienden a ser mas localizados o estacionales.',
    'methodology.sentiment_title': 'Sentimiento de la Comunidad',
    'methodology.sentiment_text': 'Debajo de los cinco pilares basados en datos de cada pais, los visitantes pueden calibrar la puntuacion de seguridad general con un simple voto de 5 niveles: demasiado alta, un poco alta, correcta, un poco baja o demasiado baja. Agregamos estos votos en una correccion de la comunidad, limitada a ±1,0 puntos para que solo pueda ajustar ligeramente la puntuacion algoritmica, nunca sustituirla. En esta primera fase, el Sentimiento de la Comunidad es solo informativo — no afecta la puntuacion de seguridad total. Podriamos integrarlo en la puntuacion en una fase futura.',
    'methodology.limitations_title': 'Limitaciones y Advertencias',
    'methodology.limitations_text': 'Nuestras puntuaciones se basan en datos disponibles publicamente que pueden estar retrasados, incompletos o no ser lo suficientemente detallados para capturar las diferencias regionales dentro de un pais. Las puntuaciones deben usarse como guia general, no como evaluaciones definitivas de seguridad. Consulta siempre los avisos de viaje oficiales de tu gobierno antes de tomar decisiones de viaje.',
    'methodology.indicator.gpi_overall': 'Indice Global de Paz - Puntuacion General',

