    'search.label': 'Rechercher des pays',
    'methodology.title': 'Comment Nous Calculons les Scores de Securite',
    'methodology.description': 'Notre methodologie de notation, nos sources de donnees et la logique derriere nos evaluations de securite.',
    'methodology.overview_title': 'Apercu',
    'methodology.overview_text': 'Nous agregeons des donnees provenant de plus de 40 sources publiques fiables pour calculer un score composite de securite (1-10) pour chaque pays. Des scores plus eleves indiquent des destinations plus sures. Notre moteur de scoring hybride utilise une moyenne geometrique ponderee sur cinq categories — Conflit (30%), Criminalite (25%), Sante (20%), Gouvernance (15%) et Environnement (10%) — afin qu\'une seule faiblesse critique (ex. guerre active) ne puisse etre masquee par de bons scores ailleurs. Des mecanismes de securite supplementaires incluent un plafond lorsqu\'une majorite de gouvernements emettent des avis "Ne pas voyager", un seuil critique qui limite le score lorsqu\'une categorie tombe en dessous d\'un niveau de danger, et un melange base sur les avis pour les pays avec une couverture de donnees limitee.',
    'methodology.sources_title': 'Sources des Donnees',
    'methodology.formula_title': 'Formule de Calcul',
    'methodology.formula_text': 'Les valeurs brutes des indicateurs sont normalisees sur une echelle de 0-1 (plus eleve = plus sur). Au sein de chaque pilier, les indicateurs ont des sous-poids explicites et sont combines via les niveaux de base (~70%) et signal (~30%) avec decroissance exponentielle de fraicheur. Le score composite utilise une moyenne geometrique ponderee des cinq piliers — contrairement a la moyenne arithmetique, la moyenne geometrique garantit qu\'un seul pilier dangereusement bas tire significativement le score global vers le bas. Trois mecanismes de securite supplementaires : (1) si une majorite d\'avis gouvernementaux atteint le Niveau 4 "Ne pas voyager", le score est plafonne proportionnellement au pilier le plus faible ; (2) si un pilier avec des donnees tombe en dessous d\'un seuil critique, le score est limite au pilier le plus faible ; (3) pour les pays avec une couverture de donnees limitee, le score est melange vers une estimation derivee des avis.',
    'methodology.tiered_title': 'Architecture Base + Signal',
    'methodology.tiered_text': 'Les sources de base (Banque Mondiale, V-Dem, INFORM, GPI) sont mises a jour annuellement et fournissent une fondation stable pour le scoring. Les sources de signaux (ReliefWeb, GDACS et 37 avis de voyage gouvernementaux de pays de tous les continents) sont mises a jour quotidiennement ou hebdomadairement et capturent les crises emergentes comme les conflits armes, les catastrophes naturelles et les epidemies. L\'influence des sources de signaux est plafonnee a 30% au sein de chaque pilier, garantissant que les donnees volatiles a court terme ne puissent pas dominer les indicateurs structurels a long terme.',
    'methodology.decay_title': 'Decroissance de la Fraicheur des Donnees',
    'methodology.decay_text': 'Chaque source de donnees a une demi-vie configuree pour la decroissance de la fraicheur. Si les donnees d\'une source ont une demi-vie d\'anciennete, elles contribuent a 50% de leur poids total ; a deux demi-vies, 25% ; et ainsi de suite. Au-dela de l\'age maximum configure, les donnees obsoletes sont entierement supprimees. Cela garantit que les scores refletent toujours les informations les plus actuelles disponibles, en se degradant progressivement lorsque les sources sont temporairement indisponibles.',
    'methodology.weights_title': 'Poids des Categories',
    'methodology.weights_text': 'Les categories sont ponderees pour refleter leur importance relative pour la securite des voyageurs. Le Conflit a le poids le plus eleve (30%) car les conflits actifs representent le risque le plus immediat et le plus grave. La Criminalite contribue a 25%, car elle affecte directement la securite personnelle au quotidien. La Sante (20%) reste importante mais est souvent gerable avec des precautions. La Gouvernance (15%) capture la stabilite institutionnelle comme facteur indirect. L\'Environnement (10%) reflete les risques naturels et climatiques qui, bien que pertinents, tendent a etre plus localises ou saisonniers.',
    'methodology.sentiment_title': 'Sentiment de la Communaute',
    'methodology.sentiment_text': 'Sous les cinq piliers bases sur les donnees de chaque pays, les visiteurs peuvent calibrer le score de securite global avec un simple vote a 5 niveaux : beaucoup trop eleve, trop eleve, juste, trop bas ou beaucoup trop bas. Nous agregeons ces votes en une correction communautaire, plafonnee a ±1,0 point afin qu\'elle ne puisse qu\'ajuster legerement le score algorithmique, jamais le remplacer. Dans cette premiere phase, le Sentiment de la Communaute est uniquement affiche — il n\'affecte pas le score de securite total. Nous pourrions l\'integrer au score dans une phase future.',
    'methodology.limitations_title': 'Limites et Mises en Garde',
    'methodology.limitations_text': 'Nos scores sont bases sur des donnees publiquement disponibles qui peuvent etre retardees, incompletes ou pas suffisamment detaillees pour capturer les differences regionales au sein d\'un pays. Les scores doivent etre utilises comme guide general, pas comme des evaluations definitives de securite. Consultez toujours les avis de voyage officiels de votre gouvernement avant de prendre des decisions de voyage.',
    'methodology.indicator.gpi_overall': 'Indice Mondial de la Paix - Score Global',

