    'methodology.description': 'Nossa metodologia de pontuacao, fontes de dados e a logica por tras das nossas avaliacoes de seguranca.',
    'methodology.overview_title': 'Visao Geral',
    'methodology.overview_text': 'Agregamos dados de mais de 40 fontes publicas confiaveis para calcular uma pontuacao composta de seguranca (1-10) para cada pais. Pontuacoes mais altas indicam destinos mais seguros. Nosso motor de pontuacao hibrido utiliza uma media geometrica ponderada de cinco categorias — Conflito (30%), Criminalidade (25%), Saude (20%), Governanca (15%) e Meio Ambiente (10%) — para que uma unica fraqueza critica (ex. guerra ativa) nao possa ser mascarada por pontuacoes altas em outros aspectos. Mecanismos de seguranca adicionais incluem um teto maximo quando a maioria dos governos emite avisos de "Nao viaje", um piso critico que limita a pontuacao quando qualquer categoria cai abaixo de um limiar de perigo, e um balanceamento baseado em avisos para paises com cobertura de dados limitada.',
    'methodology.sources_title': 'Fontes de Dados',
    'methodology.formula_title': 'Formula de Calculo',
    'methodology.formula_text': 'Os valores brutos dos indicadores sao normalizados em uma escala de 0-1 (maior = mais seguro). Dentro de cada pilar, os indicadores tem sub-pesos explicitos e sao combinados via niveis de base (~70%) e sinal (~30%) com decaimento exponencial de frescura. A pontuacao composta utiliza uma media geometrica ponderada dos cinco pilares — ao contrario da media aritmetica, a media geometrica garante que um unico pilar perigosamente baixo arraste significativamente a pontuacao geral. Tres mecanismos de seguranca adicionais: (1) se a maioria dos avisos governamentais atinge o Nivel 4 "Nao viaje", a pontuacao e limitada proporcionalmente ao pilar mais fraco; (2) se algum pilar com dados cai abaixo de um limiar critico, a pontuacao e limitada ao pilar mais fraco; (3) para paises com cobertura de dados limitada, a pontuacao e balanceada em direcao a uma estimativa derivada dos avisos.',
    'methodology.tiered_title': 'Arquitetura Base + Sinal',
    'methodology.tiered_text': 'As fontes de base (Banco Mundial, V-Dem, INFORM, GPI) sao atualizadas anualmente e fornecem uma base estavel para a pontuacao. As fontes de sinal (ReliefWeb, GDACS e 37 avisos de viagem governamentais de paises de todos os continentes) sao atualizadas diaria ou semanalmente e capturam crises emergentes como conflitos armados, desastres naturais e surtos de doencas. A influencia das fontes de sinal e limitada a 30% dentro de cada pilar, garantindo que dados volateis de curto prazo nao dominem os indicadores estruturais de longo prazo.',
    'methodology.decay_title': 'Decaimento de Frescura dos Dados',
    'methodology.decay_text': 'Cada fonte de dados tem uma meia-vida configurada para o decaimento de frescura. Se os dados de uma fonte tem uma meia-vida de idade, contribuem com 50% do seu peso total; com duas meias-vidas, 25%; e assim por diante. Alem da idade maxima configurada, dados obsoletos sao eliminados completamente. Isso garante que as pontuacoes sempre reflitam as informacoes mais atuais disponiveis, degradando-se gradualmente quando as fontes estao temporariamente indisponiveis.',
    'methodology.weights_title': 'Pesos das Categorias',
    'methodology.weights_text': 'As categorias sao ponderadas para refletir sua importancia relativa para a seguranca dos viajantes. O Conflito tem o maior peso (30%) porque os conflitos ativos representam o risco mais imediato e grave. A Criminalidade contribui com 25%, pois afeta diretamente a seguranca pessoal no dia a dia. A Saude (20%) continua importante, mas e frequentemente gerenciavel com precaucoes. A Governanca (15%) captura a estabilidade institucional como fator indireto. O Meio Ambiente (10%) reflete os riscos naturais e climaticos que, embora relevantes, tendem a ser mais localizados ou sazonais.',
    'methodology.sentiment_title': 'Sentimento da Comunidade',
    'methodology.sentiment_text': 'Abaixo dos cinco pilares baseados em dados de cada pais, os visitantes podem calibrar a pontuacao de seguranca geral com um voto simples de 5 niveis: muito alta, um pouco alta, correta, um pouco baixa ou muito baixa. Agregamos estes votos numa correcao da comunidade, limitada a ±1,0 ponto para que possa apenas ajustar ligeiramente a pontuacao algoritmica, nunca substitui-la. Nesta primeira fase, o Sentimento da Comunidade e apenas exibido — nao afeta a pontuacao de seguranca total. Podemos integra-lo na pontuacao numa fase futura.',
    'methodology.limitations_title': 'Limitacoes e Ressalvas',
    'methodology.limitations_text': 'Nossas pontuacoes sao baseadas em dados publicamente disponiveis que podem estar atrasados, incompletos ou nao suficientemente detalhados para capturar as diferencas regionais dentro de um pais. As pontuacoes devem ser usadas como guia geral, nao como avaliacoes definitivas de seguranca. Consulte sempre os avisos de viagem oficiais do seu governo antes de tomar decisoes de viagem.',
    'methodology.indicator.gpi_overall': 'Indice Global da Paz - Pontuacao Geral',

