    'about.project_title': 'O Projeto',
    'about.project_text': 'IsItSafeToTravel e uma plataforma gratuita e de codigo aberto para seguranca em viagens que fornece pontuacoes de seguranca compostas para 248 paises no mundo. As pontuacoes sao calculadas diariamente a partir de 7 fontes publicas confiaveis: Banco Mundial, V-Dem Institute (v16), INFORM, Global Peace Index, ReliefWeb, GDACS e avisos de viagem governamentais dos EUA, Reino Unido, Canada e Australia.',
    'about.mission_title': 'Missao',
    'about.mission_text': 'Nossa missao e tornar as informacoes sobre seguranca em viagens transparentes, acessiveis e baseadas em dados. Cada pontuacao e respaldada por fontes publicamente verificaveis, e nossa metodologia e totalmente documentada.',
