    'methodology.description': '我们的评分方法、数据来源以及安全评级背后的依据。',
    'methodology.overview_title': '概述',
    'methodology.overview_text': '我们聚合 40+ 个可信公开来源的数据，为每个国家计算 1-10 的综合安全评分。评分越高表示目的地越安全。我们的混合评分引擎采用五个类别的加权几何平均 — 冲突（30%）、犯罪（25%）、健康（20%）、治理（15%）和环境（10%） — 这样单一关键弱点（例如正在进行的战争）就不会被其他高分掩盖。其他安全机制包括：当多数政府发布"请勿前往"建议时设置硬性上限；当任何类别低于危险阈值时设置关键下限；以及对数据覆盖有限的国家采用基于建议的混合评分。',
    'methodology.sources_title': '数据来源',
    'methodology.formula_title': '评分公式',
    'methodology.formula_text': '原始指标值被规范化到 0-1 范围（越高越安全）。在每个支柱内，指标具有显式的子权重，并通过基线（约 70%）和信号（约 30%）层级以指数新鲜度衰减进行混合。综合评分使用五个支柱评分的加权几何平均 — 与算术平均不同，几何平均确保单一危险低分会显著拉低整体评分。还应用了三种额外的安全机制：(1) 如果多数政府旅行建议达到 4 级"请勿前往"，评分会按最弱支柱比例封顶；(2) 如果任何有数据的支柱低于关键阈值，评分会被限制到最弱支柱；(3) 对于数据覆盖有限的国家，评分会向基于建议的估计值靠拢。',
    'methodology.tiered_title': '基线 + 信号架构',
    'methodology.tiered_text': '基线来源（世界银行、V-Dem、INFORM、GPI）每年更新，为评分提供稳定基础。信号来源（ReliefWeb、GDACS 以及来自全球各大洲 37 个政府的旅行建议）每日或每周更新，捕捉武装冲突、自然灾害和疾病暴发等新出现的危机。每个支柱内信号来源的影响上限为 30%，确保短期波动数据不会主导长期结构性指标。',
    'methodology.decay_title': '数据新鲜度衰减',
    'methodology.decay_text': '每个数据源都设有新鲜度衰减半衰期。如果一个来源的数据已存在一个半衰期，则贡献其全部权重的 50%；两个半衰期为 25%；以此类推。超过配置的最大年龄后，过期数据会被完全丢弃。这确保评分始终反映可用的最新信息，并在来源临时不可用时优雅降级。',
    'methodology.weights_title': '类别权重',
    'methodology.weights_text': '类别按其对旅行者安全的相对重要性加权。冲突权重最高（30%），因为正在进行的冲突构成最直接、最严重的风险。犯罪贡献 25%，因为它直接影响日常人身安全。健康（20%）依然重要，但通常可通过预防措施进行管理。治理（15%）作为间接因素捕捉机构稳定性。环境（10%）反映自然和气候灾害，虽然相关，但往往更具地区性或季节性。',
    'methodology.sentiment_title': '社区情绪',
    'methodology.sentiment_text': '在每个国家基于数据的五大支柱下方，访客可以通过简单的 5 级投票来校准整体安全评分：偏高很多、偏高、恰好合适、偏低或偏低很多。我们将这些投票汇总为一个社区修正值，上限为 ±1.0 分，因此它只能微调算法评分，永远不会取而代之。在第一阶段，社区情绪仅供展示 — 不影响总安全评分。我们未来可能会将其纳入评分计算。',
    'methodology.limitations_title': '局限与说明',
    'methodology.limitations_text': '我们的评分基于公开可用数据，这些数据可能存在延迟、不完整，或粒度不足以捕捉一国内部的区域差异。评分应作为一般指引，而非确定性的安全评估。在做出旅行决定前，请务必查阅您所在国家政府的官方旅行建议。',
    'methodology.indicator.gpi_overall': '全球和平指数 — 总体评分',
