    'legal.section1_title': '信息用途',
    'legal.section1_text': 'IsItSafeToTravel.com 提供的安全评分、数据和内容仅供一般信息参考。本网站不提供旅行建议，所呈现的信息不应被视为专业或官方指导的替代品。',
    'legal.section2_title': '不构成旅行建议',
    'legal.section2_text': '本网站上的任何内容均不构成旅行建议或访问/避开任何目的地的推荐。旅行决策涉及个人风险评估，任何评分系统都无法完全捕捉。您应始终查阅您所在国家政府的官方旅行建议并行使自己的判断。',
    'legal.section3_title': '官方旅行建议',
