    'legal.privacy_text': 'IsItSafeToTravel.com 致力于保护您的隐私。本节说明我们的数据处理实践。',
    'legal.privacy_cookies_title': 'Cookies 与跟踪',
    'legal.privacy_cookies_text': '本网站不使用 Cookies。我们不设置任何第一方或第三方 Cookies。客户端唯一使用的存储是 localStorage，用于记住您的主题偏好（浅色/深色模式），根据 ePrivacy 指令属于严格必要，无需同意。',
    'legal.privacy_analytics_title': '分析',
    'legal.privacy_analytics_text': '我们使用 Cloudflare Web Analytics 和 Microsoft Clarity。Cloudflare Web Analytics 是一项尊重隐私的服务，不使用 Cookies，不收集个人数据，也不跟踪个人用户。它提供页面浏览、来源和地理区域等聚合统计。Microsoft Clarity 记录匿名化的用户交互（点击、滚动、导航）以帮助我们改进可用性。Clarity 自动屏蔽敏感内容，不收集个人数据，且不使用跨站点跟踪 Cookies。两项服务均不收集或存储任何可识别个人身份的信息。',
    'legal.privacy_data_title': '数据处理',
    'legal.privacy_data_text': '本网站不收集、存储或处理任何个人数据。我们没有用户账户、登录表单、联系表单或任何收集个人信息的机制。所显示的安全评分和数据均聚合自公开来源，不包含个人数据。',
    'legal.privacy_hosting_title': '托管',
    'legal.privacy_hosting_text': '本网站托管在 Cloudflare Pages。Cloudflare 可能在其基础设施提供网页服务的过程中处理技术数据（如 IP 地址）。该处理受 Cloudflare 隐私政策约束。我们无法访问个别访客数据。',
    'legal.privacy_rights_title': '您的权利',
    'legal.privacy_rights_text': '由于我们不收集个人数据，因此没有可供访问、更正或删除的个人数据。如有任何隐私相关问题，请通过下方信息与我们联系。',
    'legal.privacy_votes_title': '社区投票',
    'legal.privacy_votes_text': '当您提交社区情绪校准投票时，我们会存储您 IP 地址的加盐哈希值，用于防止滥用和检测重复投票 — 我们绝不存储您的原始 IP 地址。启用 Cloudflare Turnstile 时，它可能会执行反机器人验证。我们还会在您浏览器的 localStorage 中保存一个标记，以避免再次要求您为已投票的国家投票；这是设备本地存储，而非 Cookie，与我们的零 Cookie 方针保持一致。',
