    'methodology.pillar.conflict.description': '衡量武装冲突强度、军事化水平以及政府旅行建议警告。本类别权重最高，因为正在进行的冲突和政府警告对旅行者构成最直接、最严重的风险。涵盖来自全球 37 个政府的旅行建议级别。',
    'methodology.pillar.conflict.sources': '全球和平指数评分以及来自全球 37 个政府的旅行建议级别（美国、英国、加拿大、澳大利亚、德国、荷兰、日本及其他 30 个）。',
    'methodology.pillar.conflict.low_score': '正在或近期发生武装冲突、政治不稳定、军事化程度高。旅行者面临较高的人身安全风险。',
    'methodology.pillar.conflict.high_score': '和平且政治稳定，冲突风险低、军事化最小。通常不受冲突相关威胁影响。',
    'methodology.pillar.crime.title': '犯罪（25%）',
    'methodology.pillar.crime.description': '衡量法治强度和法律保护水平。强有力的法治意味着对居民和访客都有有效的法律保护与执法。',
    'methodology.pillar.crime.sources': 'V-Dem 法治指数（Coppedge et al., V-Dem Institute v16, CC-BY-SA 4.0）。',
    'methodology.pillar.crime.low_score': '法治薄弱，法律救济有限。旅行者面临较高犯罪风险与有限保护。',
    'methodology.pillar.crime.high_score': '法律保护强、执法有效。旅行者享有低犯罪率和健全的法律体系。',
    'methodology.pillar.health.title': '健康（20%）',
    'methodology.pillar.health.description': '衡量医疗体系质量和流行病或疾病风险。可靠的医疗服务和较低的疾病流行率是旅行者安全的关键因素。',
    'methodology.pillar.health.sources': '世界银行儿童死亡率（医疗质量代理指标）、INFORM 健康风险指数、INFORM 流行病风险指数。',
    'methodology.pillar.health.low_score': '医疗服务受限，疾病或流行病风险升高。旅行者获得医疗护理可能面临困难。',
    'methodology.pillar.health.high_score': '医疗基础设施健全，流行病风险低。可获得高质量医疗服务，疾病风险最小。',
    'methodology.pillar.governance.title': '治理（15%）',
    'methodology.pillar.governance.description': '衡量机构效能与腐败水平。治理良好的国家通过可靠的公共服务和透明的机构，为旅行者提供更可预测、更安全的环境。',
    'methodology.pillar.governance.sources': 'V-Dem 公共行政质量、V-Dem 政治腐败指数（反向）、INFORM 治理指数。',
    'methodology.pillar.governance.low_score': '机构薄弱、腐败严重、治理脆弱。旅行者可能遇到不可靠的公共服务和官僚障碍。',
    'methodology.pillar.governance.high_score': '政府机构有效、透明。公共服务可靠，腐败得到良好控制。',
    'methodology.pillar.environment.title': '环境（10%）',
    'methodology.pillar.environment.description': '衡量自然灾害暴露和环境健康风险。虽然往往是季节性或区域性的，自然灾害和空气污染可显著影响旅行安全。包括 ReliefWeb 人道主义灾难和 GDACS 自然灾害预警，用于近实时监测。',
    'methodology.pillar.environment.sources': '世界银行空气污染（PM2.5）、INFORM 自然灾害风险指数、INFORM 气候风险指数、ReliefWeb 活跃人道主义灾难、GDACS 自然灾害预警。',
    'methodology.pillar.environment.low_score': '高度暴露于自然灾害、严重空气污染、气候相关灾害。旅行者应密切监测天气和环境状况。',
    'methodology.pillar.environment.high_score': '自然灾害风险低、空气质量良好。环境条件总体上有利于旅行者。',
