    'methodology.title': 'Wie wir Sicherheitsbewertungen berechnen',
    'methodology.description': 'Unsere Bewertungsmethodik, Datenquellen und die Begründung hinter unseren Sicherheitsbewertungen.',
    'methodology.overview_title': 'Überblick',
    'methodology.overview_text': 'Wir aggregieren Daten aus 40+ vertrauenswürdigen öffentlichen Quellen, um eine zusammengesetzte Sicherheitsbewertung (1-10) für jedes Land zu berechnen. Höhere Werte stehen für sicherere Reiseziele. Unser hybrides Bewertungssystem verwendet einen gewichteten geometrischen Mittelwert über fünf Kategorien — Konflikt (30%), Kriminalität (25%), Gesundheit (20%), Regierungsführung (15%) und Umwelt (10%) — sodass eine einzelne kritische Schwäche (z. B. aktiver Krieg) nicht durch starke Werte in anderen Bereichen verdeckt werden kann. Zusätzliche Sicherheitsmechanismen umfassen eine harte Obergrenze, wenn die Mehrheit der Reisehinweise „Nicht reisen" empfiehlt, eine kritische Untergrenze, wenn eine Kategorie unter eine Gefahrenschwelle fällt, sowie eine reisehinweis-basierte Mischung für Länder mit begrenzter Datenabdeckung.',
    'methodology.sources_title': 'Datenquellen',
    'methodology.formula_title': 'Berechnungsformel',
    'methodology.formula_text': 'Rohwerte der Indikatoren werden auf eine Skala von 0-1 normalisiert (höher = sicherer). Innerhalb jeder Säule haben Indikatoren explizite Untergewichte und werden über Basis- (~70%) und Signalebenen (~30%) mit exponentieller Frische-Abnahme gemischt. Die Gesamtbewertung verwendet einen gewichteten geometrischen Mittelwert der fünf Säulenbewertungen — anders als ein arithmetischer Mittelwert stellt der geometrische Mittelwert sicher, dass eine einzige gefährlich niedrige Säule die Gesamtbewertung deutlich nach unten zieht. Drei zusätzliche Sicherheitsmechanismen gelten: (1) Wenn die Mehrheit der Reisehinweise Stufe 4 „Nicht reisen" erreicht, wird die Bewertung proportional zur schwächsten Säule begrenzt; (2) wenn eine Säule mit Daten unter einen kritischen Schwellenwert fällt, wird die Bewertung auf die schwächste Säule begrenzt; (3) für Länder mit begrenzter Datenabdeckung mischt sich die Bewertung in Richtung einer aus Reisehinweisen abgeleiteten Schätzung.',
    'methodology.tiered_title': 'Basis- + Signal-Architektur',
    'methodology.tiered_text': 'Basisquellen (Weltbank, V-Dem, INFORM, GPI) werden jährlich aktualisiert und liefern eine stabile Bewertungsgrundlage. Signalquellen (ReliefWeb, GDACS und 37 staatliche Reisehinweise aus Ländern aller Kontinente) werden täglich oder wöchentlich aktualisiert und erfassen aufkommende Krisen wie bewaffnete Konflikte, Naturkatastrophen und Krankheitsausbrüche. Der Einfluss der Signalquellen ist innerhalb jeder Säule auf 30% begrenzt, sodass volatile Kurzzeitdaten die langfristigen strukturellen Indikatoren nicht dominieren können.',
    'methodology.decay_title': 'Datenfrische-Abnahme',
    'methodology.decay_text': 'Jede Datenquelle hat eine konfigurierte Halbwertszeit für die Frische-Abnahme. Sind die Daten einer Quelle eine Halbwertszeit alt, tragen sie 50% ihres vollen Gewichts bei; bei zwei Halbwertszeiten 25%; und so weiter. Über das konfigurierte Höchstalter hinaus werden veraltete Daten vollständig verworfen. Dies stellt sicher, dass die Bewertungen stets die aktuellsten verfügbaren Informationen widerspiegeln und sich elegant verschlechtern, wenn Quellen vorübergehend nicht verfügbar sind.',
    'methodology.weights_title': 'Kategoriegewichte',
    'methodology.weights_text': 'Die Kategorien sind gewichtet, um ihre relative Bedeutung für die Sicherheit der Reisenden widerzuspiegeln. Konflikt trägt das höchste Gewicht (30%), da aktive Konflikte das unmittelbarste und schwerwiegendste Risiko darstellen. Kriminalität steuert 25% bei, da sie die persönliche Sicherheit im Alltag direkt beeinflusst. Gesundheit (20%) bleibt wichtig, ist aber oft mit Vorsichtsmaßnahmen beherrschbar. Regierungsführung (15%) erfasst die institutionelle Stabilität als indirekten Faktor. Umwelt (10%) spiegelt natürliche und klimatische Gefahren wider, die zwar relevant, aber häufig lokalisiert oder saisonal sind.',
    'methodology.sentiment_title': 'Community-Stimmung',
    'methodology.sentiment_text': 'Unterhalb der fünf datengestützten Säulen jedes Landes können Besucher die Gesamt-Sicherheitsbewertung mit einer einfachen 5-Stufen-Abstimmung kalibrieren: viel zu hoch, zu hoch, genau richtig, zu niedrig oder viel zu niedrig. Wir aggregieren diese Stimmen zu einer Community-Korrektur, die auf ±1,0 Punkte begrenzt ist, sodass sie den algorithmischen Score nur leicht anpassen, aber niemals außer Kraft setzen kann. In dieser ersten Phase ist die Community-Stimmung rein informativ — sie hat keinen Einfluss auf die Gesamt-Sicherheitsbewertung. Wir könnten sie in einer zukünftigen Phase in die Bewertung einfließen lassen.',
    'methodology.limitations_title': 'Einschränkungen und Vorbehalte',
    'methodology.limitations_text': 'Unsere Bewertungen basieren auf öffentlich verfügbaren Daten, die verzögert, unvollständig oder nicht detailliert genug sein können, um regionale Unterschiede innerhalb eines Landes abzubilden. Bewertungen sollten als allgemeine Orientierung dienen, nicht als endgültige Sicherheitsbeurteilungen. Konsultieren Sie vor Reiseentscheidungen stets die offiziellen Reisehinweise Ihrer Regierung.',
